{
  "type": "record",
  "name": "OrderPlaced",
  "namespace": "com.acme.orders.v1",
  "doc": "A customer order was accepted. Emitted once per order, never amended.",
  "fields": [
    { "name": "orderId",   "type": { "type": "string", "logicalType": "uuid" } },
    { "name": "occurredAt","type": { "type": "long", "logicalType": "timestamp-micros" } },
    { "name": "total",     "type": { "type": "bytes", "logicalType": "decimal", "precision": 12, "scale": 2 } },
    { "name": "couponCode","type": ["null", "string"], "default": null }
  ]
}
